#include <cstdio>
#include <cstring>
using namespace std;

int n;
int a[100005];
int state[100005];

int main() {
    scanf("%d", &n);
    memset(state, -1, sizeof(state)); // Initialize state array in one go instead of inside the loop

    for(int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    int ans = 0;
    for(int i = 0; i < n; i++) {
        if(state[i] != -1) continue; // Skip already processed
        int p = i, c = 0;
        while(state[p] == -1) {
            state[p] = (c << 16) | i; // Store c and i in one integer
            c++;
            p = (p + a[p]) % n;
        }
        if((state[p] & 0xFFFF) == i) ans += (c - (state[p] >> 16));
    }

    printf("%d\n", ans);
    return 0;
}

